data-maze.codeExample:
const queue = [start];
const visited = new Set([key(start)]);

while (queue.length) {
  const current = queue.shift();
  for (const next of neighbors(current)) {
    if (isWalkable(next) && !visited.has(key(next))) {
      visited.add(key(next));
      queue.push(next);
    }
  }
}

